#!/usr/bin/env python3
import json,pathlib,argparse,html,subprocess
p=argparse.ArgumentParser();p.add_argument('output');p.add_argument('--catalog',default=str(pathlib.Path(__file__).parent/'catalog.json'));p.add_argument('--location',default='Abbey Road, London');p.add_argument('--fps',default='29.97');a=p.parse_args();root=pathlib.Path(a.output).resolve()
items=json.loads(pathlib.Path(a.catalog).read_text())
items=[i for i in items if all((root/folder/f'{i["slug"]}.{extension}').exists() for folder,extension in [('videos','mp4'),('stills','png'),('metrics','json')])]
for i in items:
 metrics=root/'metrics'/f'{i["slug"]}.json'
 i['metrics']=json.loads(metrics.read_text()) if metrics.exists() else {}
 i['bytes']=(root/'videos'/f'{i["slug"]}.mp4').stat().st_size
 i['recommended']=i['slug'] in ['graphite','cyanotype','isobars','risograph','woodcut','woven','mineral','phosphor']
items.sort(key=lambda item: not item['recommended'])
(root/'thumbnails').mkdir(exist_ok=True)
for item in items:
 thumb=root/'thumbnails'/f'{item["slug"]}.jpg'
 if not thumb.exists():
  subprocess.run(['ffmpeg','-v','error','-y','-i',str(root/'stills'/f'{item["slug"]}.png'),'-vf','scale=320:180','-q:v','3',str(thumb)],check=True)
data=json.dumps(items).replace('<','\\u003c')
showreel_link='<a href="showreel.mp4">Watch the 40-second collection film</a> · ' if (root/'showreel.mp4').exists() else ''
for filename,label in [('CURATION.md','Selection notes'),('MEASUREMENTS.md','Local measurements')]:
 if (root/filename).exists():showreel_link+=f'<a href="{filename}">{label}</a> · '
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Living Ink — Moving studies</title><style>
*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#080808;color:#e6e6e3;font:14px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace}button,a,input{font:inherit}button,a{color:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #eee;outline-offset:4px}header{display:flex;align-items:baseline;justify-content:space-between;gap:20px;padding:24px 32px 18px}header h1{font-weight:400;font-size:18px;margin:0}header p{margin:0;color:#92928e;font-size:11px}main{padding:0 32px 32px;display:grid;grid-template-columns:minmax(0,1fr) 238px;gap:28px}.screen{background:#000;aspect-ratio:16/9;display:flex;align-items:center;position:relative}.screen video{width:100%;height:100%;display:block;object-fit:contain}.caption{display:flex;justify-content:space-between;align-items:baseline;gap:24px;margin-top:18px}.caption h2{margin:0;font-size:22px;font-weight:400;line-height:1.3}.caption p{margin:8px 0;color:#aaa;max-width:65ch;font-size:12px}.downloads{display:flex;gap:16px;flex-wrap:wrap;font-size:11px;color:#b7b7b3}.downloads a{text-underline-offset:4px}.meta{color:#888;font-size:10px;margin:10px 0 20px}aside h2{font-size:11px;font-weight:400;margin:0 0 12px;color:#aaa}nav{display:grid;gap:3px;max-height:calc(100vh - 130px);overflow-y:auto;scrollbar-width:thin}nav button{display:flex;align-items:center;gap:12px;text-align:left;border:1px solid transparent;padding:6px;background:none;font-size:11px}nav button:hover{background:#161616}nav button[aria-pressed=true]{border-color:#aaa;background:#151515}nav img{width:78px;aspect-ratio:16/9;object-fit:cover;background:#191919}nav span{display:block}nav small{display:block;font-size:9px;color:#888;margin-top:3px}.signature{border-top:1px solid #292929;padding-top:16px;margin-top:24px;color:#969692;font-size:11px;max-width:82ch}.signature strong{font-weight:400;color:#d5d5d0}.error{color:#e6b59c;min-height:1.6em;font-size:11px}details{font-size:10px;color:#888;margin-top:16px}summary{cursor:pointer}details p{max-width:78ch}.transport{display:flex;align-items:center;gap:16px;margin-top:14px}.transport button{background:none;border:1px solid #555;padding:6px 12px;font-size:11px}.transport .position{margin-left:auto;color:#888;font-size:10px}footer{padding:0 32px 30px;color:#777;font-size:10px}footer a{text-underline-offset:3px}@media(min-width:1700px){main{grid-template-columns:minmax(0,1fr) 280px}nav img{width:100px}}@media(max-width:850px){header{padding:20px;display:block}header p{margin-top:6px}main{padding:0 20px 24px;grid-template-columns:1fr;gap:20px}nav{max-height:none;grid-template-columns:repeat(2,minmax(0,1fr))}nav img{width:64px}.caption{display:block}.downloads{margin-top:12px}footer{padding:0 20px 24px}}@media(max-width:420px){nav{grid-template-columns:1fr}.caption h2{font-size:19px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style></head><body><header><h1>Living Ink / Moving studies</h1><p id="collection-count"></p></header><main><section aria-label="Selected artwork"><div class="screen"><video id="film" controls muted playsinline loop preload="metadata"></video></div><div class="transport"><button id="play">Play</button><button id="previous" aria-label="Previous study">Previous</button><button id="next" aria-label="Next study">Next</button><span class="position" id="position"></span></div><div class="caption"><div><h2 id="title"></h2><p id="description"></p></div><div class="downloads"><a id="download" download>Download video</a><a id="preset" download>Preset</a></div></div><p class="meta" id="meta"></p><p class="error" id="error" role="status"></p><p class="signature"><strong>The motion is the signature.</strong> Every study uses the live artwork’s same psychedelic distortion: the same wave shape, strength, and eight-second cycle. The surface changes from one material to the next. The movement belongs to the whole collection.</p><details><summary>About these studies</summary><p>Rendered locally with the native Rust drawing engine from the same recorded __LOCATION__ footage. Every source frame is preserved at 1920 × 1080 and __FPS__ fps. The videos are individual studies, not seamless loops; the recording returns to its beginning on replay.</p><p>Switching studies preserves your position in the recording. Only the selected video loads. The public livestream retains its current look.</p><p id="timing"></p></details></section><aside><h2>Select a study</h2><nav id="studies" aria-label="Artworks"></nav></aside></main><footer>__LOCATION__. Studies developed September 2026. __SHOWREEL__<a href="README.md">Collection notes</a></footer><script>
const items=__CATALOG__;let selected=0;let pendingTime=0;let shouldPlay=false;const film=document.querySelector('#film');const el=id=>document.getElementById(id);el('collection-count').textContent=items.length+' video studies · 1080p';
for(let index=0;index<items.length;index++){const item=items[index];const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed','false');const image=document.createElement('img');image.src='thumbnails/'+item.slug+'.jpg';image.alt='';image.loading='lazy';const label=document.createElement('span');label.textContent=item.name;if(item.recommended){const note=document.createElement('small');note.textContent='Shortlist';label.append(note)}button.append(image,label);button.addEventListener('click',()=>select(index));el('studies').append(button)}
function select(index){pendingTime=Number.isFinite(film.currentTime)?film.currentTime:0;shouldPlay=!film.paused;film.pause();selected=(index+items.length)%items.length;const item=items[selected];el('title').textContent=item.name;el('description').textContent=item.description;el('position').textContent=(selected+1)+' / '+items.length;el('download').href='videos/'+item.slug+'.mp4';el('preset').href='presets/'+item.slug+'.json';el('meta').textContent='1920 × 1080 · __FPS__ fps · '+(item.metrics.duration_seconds||0).toFixed(1)+' seconds · '+(item.bytes/1048576).toFixed(1)+' MB';el('timing').textContent='Local render measurement: '+(item.metrics.frame_p50_ms||0).toFixed(1)+' ms per frame (median). This is a local measurement, not an estimate of a production hosting bill.';el('error').textContent='';film.poster='stills/'+item.slug+'.png';film.src='videos/'+item.slug+'.mp4';film.setAttribute('aria-label',item.name);[...el('studies').children].forEach((button,i)=>button.setAttribute('aria-pressed',String(i===selected)));history.replaceState(null,'','#'+item.slug)}
el('play').onclick=()=>{if(film.paused)film.play().catch(()=>{el('error').textContent='Playback could not start. Select another study.'});else film.pause()};film.addEventListener('play',()=>el('play').textContent='Pause');film.addEventListener('pause',()=>el('play').textContent='Play');
film.addEventListener('loadedmetadata',()=>{film.currentTime=Math.min(pendingTime,Math.max(0,film.duration-0.1));if(shouldPlay)film.play().catch(()=>{el('error').textContent='Press Play to watch this study.'})});film.addEventListener('error',()=>{el('error').textContent='This video could not load. Select another study or reload the page.'});document.addEventListener('visibilitychange',()=>{if(document.hidden)film.pause()});el('previous').onclick=()=>select(selected-1);el('next').onclick=()=>select(selected+1);const hash=location.hash.slice(1);select(Math.max(0,items.findIndex(i=>i.slug===hash)));
</script></body></html>'''.replace('__CATALOG__',data).replace('__SHOWREEL__',showreel_link).replace('__LOCATION__',html.escape(a.location)).replace('__FPS__',html.escape(a.fps))
(root/'index.html').write_text(page)
print(root/'index.html')
